import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"Manage LIVE connections","description":"","frontmatter":{"title":"Manage LIVE connections","docId":"user.live.connections","translationKey":"user.live.connections","locale":"en","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"446118d4c202b645dd93867f1715484cbd9876f940ba229ac26e4b7f24bc4cbc","translationRevision":"446118d4c202b645dd93867f1715484cbd9876f940ba229ac26e4b7f24bc4cbc","order":10},"headers":[],"relativePath":"en/user/live/connections.md","filePath":"en/user/live/connections.md","lastUpdated":1795735295000}`),s={name:`en/user/live/connections.md`};function c(a,o,s,c,l,u){let d=e(`DemoFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="manage-live-connections" tabindex="-1">Manage LIVE connections <a class="header-anchor" href="#manage-live-connections" aria-label="Permalink to “Manage LIVE connections”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Goal and prerequisites”">​</a></h2><p>Connect to a specific creator, understand reconnection, and configure plugin servers independently. You need a working <a href="./../installation.html">desktop installation</a>, network access, and the creator&#39;s handle. Check <a href="./../requirements.html">requirements</a> before diagnosing operating system problems.</p><h2 id="connect-deliberately" tabindex="-1">Connect deliberately <a class="header-anchor" href="#connect-deliberately" aria-label="Permalink to “Connect deliberately”">​</a></h2><ol><li>Open <strong>Connections</strong>. Enter the handle, with or without <code>@</code>; a display name is not the same identifier.</li><li>Start with <strong>Use Cookie</strong> off. If TikTok requires an authorized session, enable it and enter the cookie only in the masked field. Cookies remain in memory; do not paste them into diagnostics or Cloud settings.</li><li>Leave <strong>Monitor and auto-connect</strong> off for a direct attempt, then select <strong>Connect</strong>. Read the status and any error before retrying.</li><li>Check <a href="./feed.html">Live feed</a> for the correct creator and a new event. A connected but quiet room may show no activity.</li><li>Use <strong>Reconnect</strong> for the same creator or <strong>Disconnect</strong> before changing creators. During a busy attempt, <strong>Cancel</strong> stops that attempt.</li></ol><p>After a successful direct connection, enable monitoring to wait for a creator to go live. Waiting and checking are distinct from being connected. Stop monitoring before editing a locked handle. Selecting a recent creator starts a connection; it is more than filling the input.</p><p>The explorer offers discovered rooms, but results can become stale. Refresh before assuming a room is still available. Plugin server connections in the lower panel configure their own services; a connected plugin does not establish TikTok or Cloud authentication.</p><h2 id="expected-result-and-status" tabindex="-1">Expected result and status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Expected result and status”">​</a></h2><p>Direct connections, monitoring and plugin connection controls are available. Reconnecting to the same creator preserves the current feed context; changing creator starts another context. Actual TikTok access depends on the upstream room and session, and is not guaranteed by a successful local test.</p><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to “Recovery”">​</a></h2><p>For offline rooms, verify that the creator is live. For session or rate-limit errors, follow the reported retry condition. Repeated reconnect clicks do not refresh authentication. Use <a href="./../preferences/troubleshooting.html">troubleshooting</a> to collect the failing component and time without exposing credentials.</p><p>Try it interactively before touching your real setup:</p>`,12),t(d,{scenario:`connection`,locale:`en`,panel:`connection`,title:`Try the LIVE connection panel`}),o[1]||=r(`<h2 id="command-line-operations" tabindex="-1">Command line operations <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “Command line operations”">​</a></h2><p>Every operation in this guide is also available from the CLI — offline, scriptable and agent-friendly. Usage lines are parser syntax and stay in English in every locale.</p><table tabindex="0"><thead><tr><th>Command</th><th>Summary</th></tr></thead><tbody><tr><td><code>tiktools live connect --unique-id &lt;id&gt; --session-cookie &lt;cookie&gt; [--room-id &lt;id&gt;]</code></td><td>connect to a live room</td></tr><tr><td><code>tiktools live pick --session-cookie &lt;cookie&gt;</code></td><td>pick a live room interactively</td></tr><tr><td><code>tiktools live channels [--keyword text] [--offset N] [--limit N] [--session-cookie &lt;cookie&gt;]</code></td><td>discover live channels; works without a session</td></tr><tr><td><code>tiktools live disconnect</code></td><td>disconnect from the current room <strong>destructive</strong></td></tr><tr><td><code>tiktools live status</code></td><td>current connection status</td></tr></tbody></table><p>See the <a href="./../../developer/cli.html">full command reference</a> for conventions, JSON output and destructive-operation markers.</p>`,4)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};